add('media', 2, 'Describe a film that you enjoyed', ['what the film was', 'who was in it and what it was about', 'where and when you watched it'], 'why you enjoyed it',
  'animated film, family, last year, cinema, humour, music, emotional',
  [`I'd like to describe an animated film that I saw last year with my family. It was about a young girl who lives in a small seaside town and discovers a hidden world beneath the waves.`,
   `The story follows her friendship with a lonely sea creature, who has lost his way and needs help getting home. Along the way, they meet a number of strange characters, including a grumpy octopus who turns out to have a big heart. There's quite a lot of adventure, because they have to avoid a dangerous storm and escape from a fishing net, but at its centre it's a story about friendship and being brave.`,
   `We watched it at the cinema on a rainy Sunday afternoon in March. My two younger cousins were with us, and my parents had decided that they would only come if they could sit at the back. By the end, though, even my father, who rarely shows emotion, was wiping his eyes.`,
   `I enjoyed it for several reasons. First, the animation was gorgeous. Every scene had rich, deep blues and greens, and the underwater lights looked incredibly realistic. Second, the music was memorable, and I've since listened to the soundtrack many times. Third, the humour worked for all ages, so both children and adults were laughing at different moments.`,
   `But what I appreciated most was the message. It wasn't preachy, yet it left me thinking about kindness and about looking after the ocean. It's rare for a film to be so entertaining and also so thoughtful, which is why I'd happily watch it again.`]);
add('media', 3, 'Describe a TV programme or series that you enjoy watching', ['what it is', 'what it is about', 'when you usually watch it'], 'why you enjoy it', 'nature documentary series, narrator, animals, photography, Sunday evenings, learning', null);
add('media', 3, 'Describe a website or app that you use often', ['what it is', 'what you use it for', 'how you found out about it'], 'why you find it useful',
  'language app, short lessons, streaks, found through friend, 10 minutes, motivation',
  [`The app that I use most often is a language-learning app that I downloaded about a year and a half ago. I use it to practise Spanish, which I'm learning because I'd like to visit South America.`,
   `I found out about it from a friend who was bragging about her long streak of daily lessons. I was sceptical at first, because I thought an app couldn't teach a language properly. But she showed me how it works, and I decided to give it a week's trial.`,
   `The app presents the language in small lessons that take about ten minutes each. Each one includes a mixture of listening, speaking, reading and simple writing tasks, and there are little games to keep it fun. It keeps a record of how many days in a row you've practised, and it sends a gentle reminder if you haven't, which I found a bit annoying at first, but now I rely on it.`,
   `I find it useful for several reasons. First of all, it fits into my schedule. I can open it on the bus, in a queue or even while the kettle's boiling. Second, it keeps me motivated, because I can see my progress and I don't want to break my streak. Finally, it's inexpensive, and the basic version is free.`,
   `Of course, it has its limitations. It doesn't replace real conversation, so I've also joined a weekly speaking group online. Nevertheless, as a way of building a daily habit, it has been very effective. I can now understand simple conversations, and that's a great feeling.`]);
add('media', 3, 'Describe an article or post you read online that was useful', ['what it was about', 'where you found it', 'what you learned from it'], 'why it was useful', 'sleep article, health site, screens, routine, tried it, better sleep', null);
add('media', 3, 'Describe a piece of music or a song that is special to you', ['what it is', 'when you first heard it', 'what it is like'], 'why it is special to you', 'old folk song, grandfather sang, melody, lullaby, memories, calm', null);
add('media', 4, 'Describe a photograph that you like', ['what the photograph shows', 'when and where it was taken', 'who took it'], 'why you like it',
  'family on beach, dawn, father took it, wind, laughing, framed',
  [`The photograph I'd like to describe is one of my family on a beach, taken about ten years ago during a summer holiday on the coast.`,
   `It shows my mother, my sister and me standing at the edge of the water, with our trousers rolled up. The sun is just rising behind us, so everything is covered in a soft orange light, and there's a long shadow on the sand. A strong wind is blowing my mother's scarf across her face, and she's laughing so much that she can hardly stand. My sister has her arms stretched out as if she's about to fly, and I'm looking at the camera with a very serious face, which now makes me laugh.`,
   `My father took it. He'd got up early to photograph the sunrise, and he asked us to join him on the beach at the last moment. He used an old film camera that he loved, so there were only thirty-six pictures on the roll, and this was the only one in which everyone looks natural. Many of the others are blurred or have somebody's eyes closed.`,
   `I like it for several reasons. Visually, the colours and the light are beautiful, and it looks almost like a painting. But, more importantly, it captures a moment of pure happiness without any posing. It reminds me of how simple our family holidays were, with no phones, no schedule and nothing to do except enjoy each other's company.`,
   `I've had it printed and put in a frame on my desk. When I'm stressed at work, I glance at it, and it immediately makes me smile and feel calmer.`]);

const checklist = ['You covered every point on the card in order', 'You explained the last part of the card ("explain why / how you felt") clearly', 'You spoke for the full 1 to 2 minutes without long gaps', 'You used past tenses for events and present tenses for descriptions', 'You gave details: names, numbers, colours, feelings', 'You linked ideas with words such as because, so, although, as a result'];
export default {
  topic: 'speaking-part2',
  items: C.map((c, i) => {
    const it = {
      id: 'sp2-' + String(i + 1).padStart(2, '0'), type: 'open', level: c.level, exams: ['academic', 'general'],
      facets: { skill: 'speaking', part: '2', qtype: 'cue' }, sub: c.sub,
      q: `<div class="cue"><p><b>${c.title}</b></p><p>You should say:</p><ul>${c.bullets.map((b) => `<li>${b}</li>`).join('')}</ul><p>and explain ${c.explain.replace(/^(explain )/, '')}.</p></div><p>You have 1 minute to prepare and can make notes. Then speak for 1 to 2 minutes.</p>`,
      timers: { prep: 60, speak: 120 }, checklist,
    };
    if (c.model) it.model = `<p><i>Notes made in the minute:</i> ${c.notes}</p>` + c.model.map((p) => `<p>${p}</p>`).join('');
    return it;
  }),
};
